"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[905],{5179:(e,t,a)=>{a.d(t,{M:()=>o,h:()=>n});let n={pve:{gladiator:"S",ranger:"S",sorcerer:"S",spiritmaster:"S",chanter:"A",assassin:"A",cleric:"B",templar:"B"},pvp:{gladiator:"S",ranger:"S",assassin:"S",templar:"A",chanter:"A",cleric:"A",sorcerer:"B",spiritmaster:"B"}},o={gladiator:"S",ranger:"S",sorcerer:"S",spiritmaster:"A",assassin:"A",templar:"B",cleric:"B",chanter:"C"}},6222:(e,t,a)=>{a.d(t,{K:()=>o});var n=a(1444);function o({id:e,name:t,prominent:a=!1}){return(0,n.jsx)("div",{className:`class-portrait${a?" prominent":""}`,children:(0,n.jsx)("img",{src:`/images/classes/${e}-640.webp`,srcSet:`/images/classes/${e}-640.webp 640w, /images/classes/${e}-1280.webp ${"spiritmaster"===e?1111:1280}w`,sizes:a?"(max-width: 767px) 100vw, 1100px":"(max-width: 767px) 100vw, 500px",alt:`AION 2 ${t} character artwork`,loading:a?"eager":"lazy",decoding:"async"})})}},7582:(e,t,a)=>{a.d(t,{Ub:()=>o,Wy:()=>n,hT:()=>i});let n={gladiator:{role:"melee",weapon:"Greatsword",intro:"Gladiator combines greatsword attacks with a durable frontline identity. NC describes it primarily as a melee attacker that can also take an off-tank role. Choose it for active close-range combat, then decide with your party who is responsible for enemy attention.",mechanic:"Several attacks build threat. Knockdown creates follow-up opportunities, while blocking connects defense to recovery and party effects. A control-immune target can change how those opportunities work.",skills:[["跳躍鑿擊","Leap toward a target to engage."],["蹂躪劍","An attack with a knockdown interaction; immune targets behave differently."],["集中格擋","A sustained frontal blocking tool that restores resources on successful blocks."]],steps:["Identify your threat-generating attacks before joining a group.","Practice engaging, moving out of a dangerous area, then returning to melee.","Try the block interaction against a manageable enemy before relying on it in a boss fight."],modes:{pve:{benefit:"Melee damage with the option to help on the front line.",tradeoff:"Threat-generating attacks require coordination with the assigned tank; defensive tools do not remove encounter mechanics.",practice:"Agree on tanking duties and watch enemy facing before committing to an attack."},pvp:{benefit:"A leap and knockdown interactions provide ways to contest close range.",tradeoff:"A target may resist control or leave melee range; an engage does not guarantee a follow-up.",practice:"Keep a way to reposition after the first approach rather than spending every movement tool at once."},solo:{benefit:"Blocking and recovery tools can support repeated close-range encounters.",tradeoff:"You still have to survive incoming attacks while maintaining melee contact.",practice:"Start with a small pull and measure whether your recovery keeps up before adding more enemies."}}},templar:{role:"tank",weapon:"Longsword and shield",intro:"Templar is the shield-focused tank in NC’s class guide. Its job involves more than surviving: keeping a useful position lets allies attack without constantly chasing or avoiding the same enemy.",mechanic:"Threat attacks, a pull and block-triggered effects support frontline control. Some control effects explicitly have different conditions for NPCs and players, so a reliable PvE action may behave differently in PvP.",skills:[["捕獲","Pulls a target toward the Templar and can apply a binding effect."],["衰弱猛擊","Available after a successful block; applies a defense-reducing effect."],["庇護一擊","Combines an attack, self-recovery and a defensive effect."]],steps:["Locate threat-generating attacks and a defensive skill on comfortable keys.","Practice holding a target in one position while avoiding its dangerous attacks.","Tell your group before using a pull that changes enemy positioning."],modes:{pve:{benefit:"A dedicated shield-and-threat toolkit for the party front line.",tradeoff:"Pulling or turning enemies at the wrong time can make the encounter harder for allies.",practice:"Establish a stable enemy position, then use defenses around incoming damage."},pvp:{benefit:"A pull creates opportunities to disrupt positioning or help a pressured ally.",tradeoff:"Player control is conditional; a target pulled into the wrong place can expose your team.",practice:"Choose a target with your group and check where it will land before using the pull."},solo:{benefit:"Block interactions and self-recovery offer a defensive approach to progression.",tradeoff:"Surviving a pull and clearing it quickly are separate goals; tank identity alone proves neither speed nor invulnerability.",practice:"Compare time spent attacking with time spent recovering before increasing pull size."}}},assassin:{role:"melee",weapon:"Daggers",intro:"Assassin uses daggers, stealth and positional attacks. Its official description emphasizes approaching from concealment and attacking from behind. It suits a player who enjoys creating an opening rather than standing in one place.",mechanic:"Marks can be built and consumed for an attack with additional control potential. Other attacks activate after a critical hit or an evade. Learn these activation conditions before treating every skill as always available.",skills:[["暗襲","Moves behind a target and has a conditional stun interaction."],["突襲","Gains damage when delivered from behind."],["紋樣爆炸","Uses accumulated marks to improve its damage and stun chance."]],steps:["Identify which attacks require a critical hit, evade or target status.","Practice reaching a target’s back without crossing a dangerous area.","Watch your marks and choose an opening before consuming them."],modes:{pve:{benefit:"Back-attack interactions reward deliberate positioning behind a stable target.",tradeoff:"Chasing positional damage during a mechanic can cost more than the bonus is worth.",practice:"Coordinate with the tank, then return to the target’s back after resolving the mechanic."},pvp:{benefit:"Stealth and a rear approach support choosing when to commit.",tradeoff:"A resisted control effect or a moving opponent can break the intended sequence.",practice:"Plan an exit before engaging and save a response for the opponent’s escape."},solo:{benefit:"A mobile approach with conditional attacks for players who enjoy active execution.",tradeoff:"An enemy facing you makes back attacks less straightforward than in a coordinated party.",practice:"Practice on one target first and track which follow-ups are actually available."}}},ranger:{role:"ranged",weapon:"Bow",intro:"Ranger uses a bow to fight at range. The official guide links this distance to battlefield awareness: the useful question is whether you can maintain a firing position while responding to what is moving toward you.",mechanic:"Some arrows can be used while moving, while other attacks are charged. A movement attack grants a precision state that interacts with follow-up skills; slows and traps add positioning options.",skills:[["套索箭","An attack that applies a movement-slowing effect."],["目標箭","Moves the character in the chosen direction and grants a precision state."],["瞄準箭","A charged attack with an additional benefit during the precision state."]],steps:["Separate mobile shots from attacks that require charging.","Practice the movement attack without moving into another enemy group.","Use terrain and a planned retreat route to maintain firing distance."],modes:{pve:{benefit:"Ranged attacks allow you to choose a firing position away from the immediate front line.",tradeoff:"Distance can also put you outside convenient healing or support range.",practice:"Find a position that preserves both a shot at the target and access to your group."},pvp:{benefit:"Slows and repositioning tools support a spacing-focused approach.",tradeoff:"Range does not guarantee safety against a gap closer, and charged attacks need an opening.",practice:"Track the opponent’s approach and keep a route to reposition before charging."},solo:{benefit:"Mobile shots and slowing effects offer tools for controlling the distance of a pull.",tradeoff:"Retreating without checking the area can attract more enemies.",practice:"Clear a safe retreat lane, then practice a small pull with movement and shots."}}},sorcerer:{role:"ranged",weapon:"Spellbook",intro:"Sorcerer is a ranged magic attacker with a burst-oriented identity. NC also describes lower health and defense, making control and positioning part of the class choice rather than an optional extra.",mechanic:"The Taiwan skill guide includes elemental damage, fire-mark interactions and water-based slowing effects. Read the requirements of the spell you intend to follow with instead of assuming every visual effect is interchangeable.",skills:[["火之標識","Read the current fire-skill descriptions together to understand their conditions."],["冰凍鎖鏈 - 冷氣波動","The guide includes water damage with movement-slowing effects."],["酷寒之風","Check the target’s immunity and the stated activation conditions before relying on control."]],steps:["Identify a safe casting position and a route out before pulling.","Read the fire-mark conditions in your current regional client.","Practice responding to an approaching enemy without committing to another long attack."],modes:{pve:{benefit:"A ranged spellcasting role for players who enjoy planning damage opportunities.",tradeoff:"The official low-defense identity makes positioning mistakes consequential.",practice:"Learn the encounter’s safe attack windows before optimizing a sequence."},pvp:{benefit:"Control and elemental attacks can pressure opponents when there is room to cast.",tradeoff:"A control-immune or rapidly approaching target changes the plan.",practice:"Keep your escape route visible and check opponent defenses before committing."},solo:{benefit:"Slowing effects can create room for ranged attacks.",tradeoff:"If control fails, the class’s defensive limitations become more relevant.",practice:"Choose manageable pulls and leave space to recover from a resisted effect."}}},spiritmaster:{role:"ranged",weapon:"Orb",intro:"Spiritmaster fights alongside elemental spirits and combines summon management with weakening effects. The official class guide describes indirect damage, status effects and sustained pressure rather than a simple stand-and-cast role.",mechanic:"Different spirits provide different interactions. The earth spirit builds threat, the water spirit can restore the caster’s spirit resource, and the wind spirit offers recovery. Summoning also connects to an elemental accumulation mechanic.",skills:[["召喚：地之精靈","Summons an earth spirit whose attacks build threat."],["召喚：水之精靈","Summons a water spirit with resource-restoring attack interactions."],["元素融合","Requires the four-element state obtained through summoning; using it consumes that state."]],steps:["Read each spirit’s function instead of choosing only by appearance.","Track your own position and your summon at the same time.","Practice reaching and consuming the elemental state against a manageable target."],modes:{pve:{benefit:"Different summons let you plan around resource, threat and recovery interactions.",tradeoff:"An earth spirit’s threat generation needs coordination with the party’s tank.",practice:"Choose the summon for the encounter and confirm its target before your next action."},pvp:{benefit:"Summons and status effects give you more than one source of pressure to manage.",tradeoff:"Watching the summon can distract from an enemy closing on the caster.",practice:"Keep your own escape path in view while issuing summon-related actions."},solo:{benefit:"An earth spirit’s threat and other spirits’ recovery/resource tools create useful options.",tradeoff:"A summon does not prove that every enemy will ignore you or that a difficult pull is safe.",practice:"Test enemy targeting with one opponent, then select the spirit that solves the immediate problem."}}},cleric:{role:"support",weapon:"Mace",intro:"Cleric is the dedicated healing identity in NC’s guide. Its practical appeal is the responsibility of keeping allies active: watching health, positioning and weakening effects while still finding safe moments to attack.",mechanic:"The healing toolkit includes ongoing group recovery, a heal with a prerequisite and a group recovery skill that removes weakening effects. Attack skills also exist, but a damage action must be weighed against an incoming recovery need.",skills:[["重生之光","Applies recurring recovery to the caster and nearby party members."],["治癒之光","Heals the caster and the lowest-health nearby party member while the prerequisite effect is active."],["痊癒光輝","Restores nearby party health and removes weakening magic."]],steps:["Put recovery and cleansing skills on keys you can reach while moving.","Learn the prerequisite for the conditional heal.","Practice keeping allies in range without standing in their incoming damage."],modes:{pve:{benefit:"Direct recovery and weakening-effect removal support the party through damage.",tradeoff:"A healing tool cannot help an ally outside its practical range or replace avoiding a mechanic.",practice:"Position for party coverage and plan recovery before the next expected hit."},pvp:{benefit:"Recovery can keep allies active while your team contests an objective.",tradeoff:"Healing responsibility also makes your position and protection important under enemy pressure.",practice:"Stay connected to teammates and communicate when you are forced to move."},solo:{benefit:"Self-recovery provides a way to manage health while progressing independently.",tradeoff:"Recovery time is not attack time; safety and clearing speed should be evaluated separately.",practice:"Alternate manageable attack windows with recovery and avoid testing survival through oversized pulls."}}},chanter:{role:"support",weapon:"Staff",intro:"Chanter is a staff-using support hybrid. NC describes ally-enhancing effects alongside secondary healing and damage responsibilities. It suits players who want to participate in combat while watching what their party needs.",mechanic:"Close-range attacks, control interactions and a recovery chant connect the combat and support sides of the kit. A secondary healing role should be agreed with the party rather than assumed to replace every dedicated recovery requirement.",skills:[["突進擊破","Closes on a target with an attack and restores the spirit resource."],["打擊碎","An attack with a conditional stun effect."],["痊癒咒語","Restores nearby party health, removes one weakening effect and adds ongoing recovery."]],steps:["Agree whether your party expects support, secondary healing or extra damage from you.","Keep the recovery chant accessible while attacking.","Check the current descriptions for overlapping party effects before duplicating them."],modes:{pve:{benefit:"Combines party enhancement with secondary recovery and combat participation.",tradeoff:"Dividing attention between attacks and support requires clear priorities.",practice:"Set a support priority with your group, then fit attacks around that responsibility."},pvp:{benefit:"An approach attack and control options accompany the supporting role.",tradeoff:"Chasing a target can separate you from allies who need your support.",practice:"Decide whether the next action should help an ally or pressure an enemy before moving."},solo:{benefit:"Attack and recovery tools allow a self-supported combat style.",tradeoff:"Party enhancement is not automatically an equal advantage when no allies are present.",practice:"Use small pulls to learn your recovery rhythm before choosing a solo setup."}}},brawler:{role:"melee",weapon:"Fist weapons",intro:"拳星 is a mobile martial fighter whose Taiwan guide centers on building rage and entering an empowered state. Its appeal is maintaining a close-range rhythm while deciding when to spend that resource.",mechanic:"The empowered state drains rage over time and ends when rage reaches zero. Some attacks change their activation conditions in that state, while listed rage-generating attacks stop restoring rage during it.",skills:[["連攻 - 重擊 - 重捶","An attack chain that restores rage outside the empowered state."],["暴走","Enters a rage-consuming state that changes skill behavior."],["連環拳","Normally requires a critical hit; that requirement is removed in the empowered state."]],steps:["Read the normal and empowered versions of each selected skill.","Practice building rage before entering the empowered state.","End a practice fight by checking how much empowered time was spent outside striking range."],modes:{pve:{benefit:"A resource-driven melee rhythm for planned attack windows.",tradeoff:"Rage continues draining during the empowered state, so forced downtime affects its use.",practice:"Build the resource, then look for an encounter window that lets you stay in contact."},pvp:{benefit:"Approach tools support getting into striking range.",tradeoff:"An opponent who creates distance can consume your empowered window without taking attacks.",practice:"Track the opponent’s escape before spending rage on a commitment."},solo:{benefit:"A repeatable build-and-spend resource loop for active melee play.",tradeoff:"Skill behavior changes between states; treating the same button identically can waste an opportunity.",practice:"Learn the two states against one enemy before adding more targets."}}}},o={pve:{title:"Build a party, not just a damage chart",description:"Compare frontline control, recovery and damage opportunities in the same encounter. An empty party responsibility matters more than adding another copy of a role you already have.",checklist:["Who keeps the enemy in a stable position?","Who handles the next recovery or cleanse?","Can each player attack while resolving mechanics?"]},pvp:{title:"Choose a fight size before choosing a tier",description:"A duel rewards different decisions from an objective fight. Evaluate the approach, the response to control and the ability to help allies; a highlight clip cannot show all three.",checklist:["Is this a duel, small group or larger fight?","What happens if the first control effect fails?","How does the class leave a losing engagement?"]},solo:{title:"Balance progress with recovery",description:"Consider an entire sequence of pulls, including downtime. The fastest attack animation does not prove the fastest progression, and strong recovery does not prove fast clearing.",checklist:["Can you keep resources across repeated pulls?","What changes when every enemy faces you?","Can you recover from a mistake without a teammate?"]}};function i(e,t,a,o,i){let r=n[e];return!!r&&("all"===t||r.role===t)&&`${o} ${i} ${r.weapon}`.toLowerCase().includes(a.trim().toLowerCase())}}}]);